package game.world;

import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import tools.jackson.databind.json.JsonMapper;

/** Shared player/NPC handover. Called in the world transaction; AI only selects an offer. */
@Service
public class HandoverService {
 @org.springframework.beans.factory.annotation.Autowired private LogisticsLedger logistics;
 private int wanted(UUID recipient,String code){int normal=db.queryForObject("select coalesce((select quantity from npc_supply_targets where actor=? and code=?),0)",Integer.class,recipient,code);return Math.max((int)Math.max(0,normal-equipment.available(recipient,code)),logistics.incomingWanted(recipient,code));}
 /** Server-only task binding. Public offers cannot supply a cost quote. */
 public UUID proposeLogistics(UUID sender,Offer offer,long needId,int version,Long unitCost,long now){
  var n=logistics.get(needId);logistics.require(needId,version,n.carrier());
  if(n.recipient()!=null&&!Boolean.TRUE.equals(db.queryForObject("select exists(select 1 from logistics_clients l join characters c on c.id=l.actor_id where l.actor_id=? and l.post_id=? and l.enabled and c.kind<>'player')",Boolean.class,n.recipient(),n.post())))throw AccountService.bad("只服务已配置的官方人员");
  boolean corpse=n.kind().equals("corpse"),delivery=Objects.equals(sender,n.carrier())&&Objects.equals(offer.recipient(),n.recipient());
  boolean transfer=!corpse&&Objects.equals(offer.recipient(),n.carrier())&&Boolean.TRUE.equals(db.queryForObject("select exists(select 1 from logistics_agents where actor_id=?)",Boolean.class,sender));
  if(corpse){if(!Objects.equals(sender,n.recipient())||!Objects.equals(offer.recipient(),n.carrier())||!corpseIds(offer.corpses()).equals(List.of(n.corpse()))||offer.lines()!=null&&!offer.lines().isEmpty()||!offer.mode().equals("gift"))throw AccountService.bad("接尸任务不匹配");}
  else if((!delivery&&!transfer)||offer.lines()==null||offer.lines().size()!=1||!offer.lines().getFirst().code().equals(n.code())||offer.lines().getFirst().quantity()>n.remaining()||offer.corpses()!=null&&!offer.corpses().isEmpty()||!offer.mode().equals("sell"))throw AccountService.bad("配送任务不匹配");
  if(unitCost!=null){var lots=logistics.lots(sender,n.code());if(!transfer||unitCost<0||lots.isEmpty()||LogisticsLedger.number(lots.getFirst(),"unit_cost")!=unitCost||LogisticsLedger.number(lots.getFirst(),"quantity")<offer.lines().getFirst().quantity())throw AccountService.bad("调货采购批次已变化");}
  else if(transfer)throw AccountService.bad("调货须按原采购成本");
  UUID id=propose(sender,offer,now);db.update("update handovers set logistics_need=?,logistics_version=?,cost_quote=? where id=? and state='pending'",needId,version,unitCost!=null,id);if(unitCost!=null)db.update("update handover_lines set price=? where offer_id=? and exists(select 1 from handovers where id=? and state='pending')",unitCost,id,id);return id;
 }
 public record Line(String code,int quantity) {}
 public record Offer(UUID recipient,String mode,List<Line> lines,UUID requestId,List<UUID> corpses) {public Offer(UUID recipient,String mode,List<Line> lines,UUID requestId){this(recipient,mode,lines,requestId,List.of());}}
 public record Accept(UUID offerId,List<Line> lines,List<UUID> corpses) {public Accept(UUID offerId,List<Line> lines){this(offerId,lines,List.of());}}
 private List<UUID> corpseIds(List<UUID> ids){if(ids==null)return List.of();if(ids.size()>100||ids.stream().anyMatch(Objects::isNull)||new HashSet<>(ids).size()!=ids.size())throw AccountService.bad("尸体必须逐具选择，不能重复");return ids.stream().sorted().toList();}
 private final JdbcTemplate db;private final SceneRuntime runtime;private final CharacterService characters;private final EquipmentService equipment;
 private final JsonMapper json=JsonMapper.builder().build();
 HandoverService(JdbcTemplate db,SceneRuntime runtime,CharacterService characters,EquipmentService equipment){this.db=db;this.runtime=runtime;this.characters=characters;this.equipment=equipment;}
 private Map<String,Object> battle(UUID actor){return db.queryForList("select b.id,b.round_number,b.turn_account_id,b.turn_points,b.turn_deadline,a.entry_round,a.sprinted from battle_actors a join battle_encounters b on b.id=a.encounter_id where b.active and a.account_id=?",actor).stream().findFirst().orElse(null);}
 private void adjacent(UUID a,UUID b){characters.requireAlive(a);characters.requireAlive(b);var p=runtime.position(a);var t=runtime.position(b);if(a.equals(b)||p==null||t==null||!p.sceneId().equals(t.sceneId())||WorldMap.distance(p.hex(),t.hex())!=1)throw AccountService.bad("交接须处于同一实际场景的相邻格");}
 private Map<String,Object> turn(UUID a,UUID b){var x=battle(a);var y=battle(b);if(x==null&&y==null)return null;if(x==null||y==null||!x.get("id").equals(y.get("id"))||!x.get("turn_account_id").equals(a)||((Number)x.get("turn_points")).intValue()<1||((Number)x.get("entry_round")).intValue()>((Number)x.get("round_number")).intValue()||Boolean.TRUE.equals(x.get("sprinted")))throw AccountService.bad("交出方须在自己的回合拥有1行动点，且未快跑");return x;}
 private String canonical(List<Line> lines){return json.writeValueAsString(lines.stream().sorted(Comparator.comparing(Line::code)).toList());}
 private List<Line> checked(List<Line> lines){if(lines==null||lines.isEmpty()||lines.size()>100)throw AccountService.bad("请选择1至100种物品");var seen=new HashSet<String>();for(var l:lines)if(l==null||l.code()==null||!seen.add(l.code())||l.quantity()<1||l.quantity()>10000)throw AccountService.bad("物品重复或数量无效");return lines;}
 public UUID propose(UUID sender,Offer offer,long now){
  if(offer==null||offer.requestId()==null||offer.recipient()==null||!Set.of("gift","sell").contains(Objects.requireNonNullElse(offer.mode(),"")))throw AccountService.bad("交接请求无效");var corpses=corpseIds(offer.corpses());var lines=offer.lines()==null?List.<Line>of():offer.lines();if(!lines.isEmpty()||corpses.isEmpty())checked(lines);String payload=offer.recipient()+":"+offer.mode()+":"+canonical(lines)+":"+corpses;
  var old=db.queryForList("select id,payload from handovers where sender=? and request_id=?",sender,offer.requestId());if(!old.isEmpty()){if(!old.getFirst().get("payload").equals(payload))throw AccountService.bad("请求编号已用于另一份报价");return (UUID)old.getFirst().get("id");}
  adjacent(sender,offer.recipient());var b=turn(sender,offer.recipient());if(db.queryForObject("select exists(select 1 from handovers where sender=? and state='pending')",Boolean.class,sender))throw AccountService.bad("请先取消现有交接");
  var prices=new HashMap<String,Long>();for(var l:lines){if(Set.of("unarmed","claws").contains(l.code())||equipment.available(sender,l.code())<l.quantity())throw AccountService.bad("可交接数量不足，预留或已装备物品不能转交");var price=db.queryForList("select buy_price from item_definitions where code=?",l.code());if(price.isEmpty()||offer.mode().equals("sell")&&price.getFirst().get("buy_price")==null)throw AccountService.bad("物品未配置售价");prices.put(l.code(),offer.mode().equals("gift")?0:((Number)price.getFirst().get("buy_price")).longValue());}
  for(UUID corpse:corpses){if(offer.mode().equals("sell"))corpsePrice(corpse);if(!db.queryForObject("select exists(select 1 from loot_containers l where id=? and carrier_id=? and kind='corpse' and not exists(select 1 from loot_items where container_id=l.id and quantity>0) and not exists(select 1 from handover_corpses where corpse_id=l.id))",Boolean.class,corpse,sender))throw AccountService.bad("尸体不在背包、未取空或已预留");}
  UUID id=UUID.randomUUID();db.update("insert into handovers(id,sender,recipient,request_id,payload,mode,scene_id,battle_id,round_number,turn_deadline,created_at) values(?,?,?,?,?,?,?,?,?,?,?)",id,sender,offer.recipient(),offer.requestId(),payload,offer.mode(),runtime.position(sender).sceneId(),b==null?null:b.get("id"),b==null?null:b.get("round_number"),b==null?null:b.get("turn_deadline"),now);
  for(var l:lines)db.update("insert into handover_lines values(?,?,?,?)",id,l.code(),l.quantity(),prices.get(l.code()));for(UUID corpse:corpses)db.update("insert into handover_corpses values(?,?,?)",id,corpse,offer.mode().equals("sell")?corpsePrice(corpse):0);return id;
 }
 public void cancel(UUID actor,UUID id){if(db.update("update handovers set state='cancelled' where id=? and state='pending' and (sender=? or recipient=?)",id,actor,actor)==0&&!db.queryForObject("select exists(select 1 from handovers where id=? and (sender=? or recipient=?))",Boolean.class,id,actor,actor))throw AccountService.bad("无权处理此交接");}
 public void cancelActor(UUID actor){db.update("update handovers set state='cancelled' where state='pending' and (sender=? or recipient=?)",actor,actor);}
 private boolean valid(Map<String,Object> h){try{if(h.get("logistics_need")!=null){var n=logistics.get(((Number)h.get("logistics_need")).longValue());if(n.version()!=((Number)h.get("logistics_version")).intValue()||!Set.of("claimed","pickup").contains(n.state())||!Objects.equals(n.carrier(),h.get("sender"))&&!Objects.equals(n.carrier(),h.get("recipient")))return false;}UUID a=(UUID)h.get("sender"),b=(UUID)h.get("recipient");adjacent(a,b);if(!runtime.position(a).sceneId().equals(h.get("scene_id")))return false;var current=turn(a,b);return current==null?h.get("battle_id")==null:current.get("id").equals(h.get("battle_id"))&&current.get("round_number").equals(h.get("round_number"))&&current.get("turn_deadline").equals(h.get("turn_deadline"));}catch(org.springframework.web.server.ResponseStatusException e){return false;}}
 public boolean prune(Set<UUID> online){boolean changed=false;for(var h:db.queryForList("select * from handovers where state='pending'")){UUID a=(UUID)h.get("sender"),b=(UUID)h.get("recipient");if(!valid(h)||!characters.get(a).npc()&&!online.contains(a)||!characters.get(b).npc()&&!online.contains(b)){db.update("update handovers set state='cancelled' where id=?",h.get("id"));changed=true;}}return changed;}
 public List<Map<String,Object>> view(UUID actor){var rows=db.queryForList("select h.*,coalesce(sa.username,nullif(a.name,''),'旅人') as sender_name,coalesce(ra.username,nullif(b.name,''),'旅人') as recipient_name from handovers h join characters a on a.id=h.sender join characters b on b.id=h.recipient left join accounts sa on sa.id=a.id left join accounts ra on ra.id=b.id where (sender=? or recipient=?) order by created_at desc limit 20",actor,actor);for(var h:rows){h.put("lines",db.queryForList("select l.*,d.name from handover_lines l join item_definitions d on d.code=l.code where offer_id=? order by code",h.get("id")));h.put("corpses",db.queryForList("select l.id,l.name,r.price from handover_corpses r join loot_containers l on l.id=r.corpse_id where r.offer_id=?",h.get("id")));}return rows;}
 public Map<String,Object> accept(UUID recipient,Accept request,long now){
  if(request==null||request.offerId()==null)throw AccountService.bad("请选择交接报价");
  var rows=db.queryForList("select * from handovers where id=? and recipient=? for update",request.offerId(),recipient);if(rows.isEmpty())throw AccountService.bad("交接不存在");var h=rows.getFirst();var corpses=corpseIds(request.corpses());var lines=request.lines()==null?List.<Line>of():request.lines();if(!lines.isEmpty()||corpses.isEmpty())checked(lines);String accepted=canonical(lines)+":"+corpses;
  if(h.get("state").equals("completed")){if(!accepted.equals(h.get("accepted")))throw AccountService.bad("已完成交接不能修改数量");return json.readValue((String)h.get("result"),Map.class);}
  if(!h.get("state").equals("pending")||!valid(h))throw AccountService.bad("交接已失效，请重新报价");UUID sender=(UUID)h.get("sender");long total=0;
  for(var l:lines){var p=db.queryForList("select quantity,price from handover_lines where offer_id=? and code=?",request.offerId(),l.code());if(p.isEmpty()||((Number)p.getFirst().get("quantity")).intValue()<l.quantity())throw AccountService.bad("接收数量超过报价");total=Math.addExact(total,Math.multiplyExact(((Number)p.getFirst().get("price")).longValue(),l.quantity()));
   if(h.get("mode").equals("sell")&&!Boolean.TRUE.equals(h.get("cost_quote"))){Long price=db.queryForObject("select buy_price from item_definitions where code=?",Long.class,l.code());if(price==null||price.longValue()!=((Number)p.getFirst().get("price")).longValue())throw AccountService.bad("价格已变化，请重新报价并确认");}
   if(characters.get(recipient).npc()&&l.quantity()>wanted(recipient,l.code()))throw AccountService.bad("NPC只接收实际需求数量");
  }
  for(UUID corpse:corpses){var quote=db.queryForList("select price from handover_corpses where offer_id=? and corpse_id=?",request.offerId(),corpse);if(quote.isEmpty())throw AccountService.bad("尸体不在本次报价中");long price=((Number)quote.getFirst().get("price")).longValue();if(h.get("mode").equals("sell")&&price!=corpsePrice(corpse))throw AccountService.bad("尸体售价变化，请重新报价");total=Math.addExact(total,price);}
  CoinPayment.Change payment=null;long c=equipment.available(recipient,"copper_coin"),s=equipment.available(recipient,"silver_coin"),g=equipment.available(recipient,"gold_coin");if(!characters.get(recipient).npc())payment=CoinPayment.pay(c,s,g,total);
  for(UUID corpse:corpses){if(characters.get(recipient).npc()&&!logistics.acceptsCorpse(recipient,sender,corpse))throw AccountService.bad("该NPC当前没有接尸任务");if(!db.queryForObject("select exists(select 1 from handover_corpses r join loot_containers l on l.id=r.corpse_id where r.offer_id=? and l.id=? and carrier_id=?)",Boolean.class,request.offerId(),corpse,sender))throw AccountService.bad("尸体已不属于本次报价");}
  db.update("update handovers set state='completed',accepted=? where id=?",accepted,request.offerId());
  for(UUID corpse:corpses)db.update("update loot_containers set carrier_id=? where id=?",recipient,corpse);
  for(var l:lines){equipment.consume(sender,l.code(),l.quantity());add(recipient,l.code(),l.quantity());}
  if(payment!=null){add(recipient,"copper_coin",payment.copper()-c);add(recipient,"silver_coin",payment.silver()-s);add(recipient,"gold_coin",payment.gold()-g);}add(sender,"copper_coin",total);
  if(h.get("logistics_need")!=null)for(var l:lines){long price=db.queryForObject("select price from handover_lines where offer_id=? and code=?",Long.class,request.offerId(),l.code());logistics.settleHandover(request.offerId(),((Number)h.get("logistics_need")).longValue(),((Number)h.get("logistics_version")).intValue(),sender,recipient,l.code(),l.quantity(),price,Boolean.TRUE.equals(h.get("cost_quote")),now);}
  var result=Map.<String,Object>of("offerId",request.offerId(),"total",total,"message","交接完成");db.update("update handovers set result=? where id=?",json.writeValueAsString(result),request.offerId());return result;
 }
 private long corpsePrice(UUID corpse){Long price=db.queryForObject("select case source_species when 'bully' then 5 when 'archer' then 3 else null end from loot_containers where id=?",Long.class,corpse);if(price==null)throw AccountService.bad("该尸体未配置售价，可赠送交接");return price;}
 public UUID sender(UUID id){return db.queryForObject("select sender from handovers where id=?",UUID.class,id);}
 public Accept npcAcceptance(UUID id){var h=db.queryForMap("select sender,recipient,state from handovers where id=?",id);UUID recipient=(UUID)h.get("recipient");if(!characters.get(recipient).npc()||!h.get("state").equals("pending"))return null;var accepted=new ArrayList<Line>();for(var l:db.queryForList("select code,quantity from handover_lines where offer_id=?",id)){String code=(String)l.get("code");int take=Math.min(((Number)l.get("quantity")).intValue(),wanted(recipient,code));if(take>0)accepted.add(new Line(code,take));}var corpses=db.queryForList("select corpse_id from handover_corpses where offer_id=?",UUID.class,id).stream().filter(c->logistics.acceptsCorpse(recipient,(UUID)h.get("sender"),c)).toList();if(accepted.isEmpty()&&corpses.isEmpty()){cancel(recipient,id);return null;}return new Accept(id,accepted,corpses);}
 public boolean completed(UUID id){return Boolean.TRUE.equals(db.queryForObject("select exists(select 1 from handovers where id=? and state='completed')",Boolean.class,id));}
 private void add(UUID actor,String code,long delta){if(delta!=0)db.update("insert into inventories(character_id,item_code,quantity) values(?,?,?) on conflict(character_id,item_code) do update set quantity=inventories.quantity+?",actor,code,Math.max(0,delta),delta);}
}
